referenceSolutions.javascript:
export function longestUniqueSubstring(text) {
  const last = new Map();
  let start = 0, best = 0;
  for (let end = 0; end < text.length; end++) {
    start = Math.max(start, (last.get(text[end]) ?? -1) + 1);
    last.set(text[end], end);
    best = Math.max(best, end - start + 1);
  }
  return best;
}

